class Job:
    def __init__(self, status, size):
        self.status = status
        self.size = size

def summarize_jobs(jobs):
    result = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status not in result:
            result[status] = {'count': 0, 'total_size': 0}
        result[status]['count'] += 1
        result[status]['total_size'] += size

    return result
