import time

def retry_read(read, attempts):
    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            if attempt < attempts - 1:
                continue
            else:
                raise
        except ValueError:
            raise
        except Exception as e:
            raise e
